import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-prefix optimizer using global and pooled-token layouts."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one cell exactly as an evaluator scoring cell."""
        try:
            missing = pd.isna(value)
            if not hasattr(missing, "__len__") and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute a longest common prefix using binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse from sorted adjacent row strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested column groups contiguous without duplicating columns."""
        if not col_merge:
            return list(order)

        positions = {column: index for index, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column
                for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert integer positions to names and apply merge constraints."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its assigned column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Construct whole-value and partial-prefix global column layouts."""
        rows = len(text)
        width = len(columns)

        whole_mass = []
        prefix_mass = []

        for column in range(width):
            values = Counter(text[row][column] for row in range(rows))

            whole = sum(
                len(value) * count * (count - 1)
                for value, count in values.items()
            )
            whole_mass.append((whole, len(values)))

            prefixes = Counter()
            for value, count in values.items():
                for length in range(1, min(8, len(value)) + 1):
                    prefixes[value[:length]] += count

            partial = sum(
                len(prefix) * count * (count - 1)
                for prefix, count in prefixes.items()
            )
            prefix_mass.append((partial, len(prefixes)))

        frequency_order = sorted(
            range(width),
            key=lambda column: (
                -whole_mass[column][0],
                whole_mass[column][1],
                column,
            ),
        )

        prefix_order = sorted(
            range(width),
            key=lambda column: (
                -prefix_mass[column][0],
                prefix_mass[column][1],
                -whole_mass[column][0],
                column,
            ),
        )

        candidates = [
            self._normalize(columns, frequency_order, col_merge),
            self._normalize(columns, prefix_order, col_merge),
        ]
        return candidates, frequency_order

    def _pooled_token_candidate(self, text, columns, col_merge, base_order):
        """Lead each row with its strongest repeated cross-column literal.

        Frequencies are pooled across all columns because the evaluator sees
        only concatenated characters.  The selected head maximizes
        len(value) * (pooled_frequency(value) - 1); all remaining columns use
        the deterministic global frequency-ranked tail.
        """
        rows = len(text)
        width = len(columns)

        fallback = self._normalize(columns, base_order, col_merge)
        if rows == 0 or width == 0:
            return []

        pooled = Counter()
        for row in text:
            pooled.update(row)

        repetition = {
            value: count - 1
            for value, count in pooled.items()
            if count > 1
        }

        base_position = {column: pos for pos, column in enumerate(base_order)}
        result = [fallback[:] for _ in range(rows)]

        for row_index, row in enumerate(text):
            best_column = None
            best_score = 0

            for column, value in enumerate(row):
                if not value:
                    continue

                score = len(value) * repetition.get(value, 0)
                if score > best_score:
                    best_score = score
                    best_column = column
                elif score == best_score and score > 0:
                    if best_column is None or (
                        base_position.get(column, width)
                        < base_position.get(best_column, width)
                    ):
                        best_column = column

            if best_column is None:
                continue

            proposed = [best_column]
            proposed.extend(
                column
                for column in base_order
                if column != best_column
            )
            result[row_index] = self._normalize(
                columns, proposed, col_merge
            )

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate bounded layouts and return the best reordered dataframe."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [
                self._text(raw[row, column])
                for column in range(width)
            ]
            for row in range(rows)
        ]

        global_orders, base_order = self._global_candidates(
            text, columns, col_merge
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append(
                (self._reuse(serialized), orders, serialized)
            )

        pooled_orders = self._pooled_token_candidate(
            text, columns, col_merge, base_order
        )
        pooled_serialized = self._serialize(text, pooled_orders)
        candidates.append(
            (
                self._reuse(pooled_serialized),
                pooled_orders,
                pooled_serialized,
            )
        )

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

